void SetMeshCastsShadow(Mesh* mesh, bool casts) {
    if (!mesh) return;
    // Toggling the flag on the mesh itself means every draw of it agrees, without
    // the caller having to track the state per draw call.
    if (casts) {
        mesh->flags &= ~MeshNoShadow;
    } else {
        mesh->flags |= MeshNoShadow;
    }
}

